const message = $json.message ?? {};
const chat = message.chat ?? {};
const chatId = chat.id;
const raw = typeof message.text === 'string' ? message.text : '';
if (chatId == null || chat.type !== 'private' || !raw.trim()) return { json: { skip: true } };
const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const textIn = normalize(raw);
const command = textIn.split(/\s+/)[0].replace(/@[^ ]+$/, '');
let accion = 'estatica';
let seccion = null;
let text;
if (command === '/vincular') { accion = 'vincular'; }
else if (/^\/(perfil|misdatos)$/.test(command)) { accion = 'consulta'; seccion = 'perfil'; }
else if (/^\/(mediciones|medicion|historial)$/.test(command) || /medicion|glucosa|presion/.test(textIn)) { accion = 'consulta'; seccion = 'mediciones'; }
else if (/^\/(medicamentos|medicamento)$/.test(command) || /medicamento|medicina|dosis|tratamiento|horario/.test(textIn)) { accion = 'consulta'; seccion = 'medicamentos'; }
else if (/^\/(alertas|misalertas)$/.test(command)) { accion = 'consulta'; seccion = 'alertas'; }
else if (/^\/(diagnosticos|diagnostico)$/.test(command)) { accion = 'consulta'; seccion = 'diagnosticos'; }
else if (/^\/(objetivos|metas)$/.test(command)) { accion = 'consulta'; seccion = 'objetivos'; }
else if (/^\/(start|ayuda|help|menu)$/.test(command) || /^(hola|buenas|buenos dias|buenas tardes)$/.test(textIn)) {
 text = 'Hola. Puedo consultar la información de tu cuenta vinculada en este chat privado:\n/perfil — datos de tu perfil\n/mediciones o /historial — últimas mediciones guardadas\n/medicamentos — medicamentos y horarios registrados\n/alertas — alertas guardadas\n/diagnosticos — diagnósticos confirmados\n/objetivos — objetivos registrados por tu médico\n/vincular — vincular Telegram\n/acceso — ayuda para entrar o registrarte\n\nEl bot muestra los datos registrados y no interpreta mediciones ni modifica tratamientos.';
} else if (/^\/(acceso)$/.test(command) || /registr|iniciar sesion|no puedo entrar|contrasena/.test(textIn)) {
 text = 'Usa el registro de la aplicación para solicitar una cuenta. El administrador debe activarla antes de iniciar sesión.';
} else if (/dolor|sintoma|me siento|urgente|emergencia/.test(textIn)) {
 text = 'No puedo valorar síntomas por Telegram. Contacta a tu profesional de salud; si hay peligro inmediato, comunícate con los servicios de emergencia de tu localidad.';
} else {
 text = 'Escribe /ayuda para consultar tu perfil, mediciones, medicamentos, alertas, diagnósticos u objetivos guardados.';
}
return { json: { chatId, accion, seccion, text } };

const chatId = $('Preparar respuesta segura').item.json.chatId;
const codigo = String($json.codigo ?? '');
const text = codigo ? `Código temporal: ${codigo}\n\nInicia sesión en la aplicación, abre “Mi información” y pega el código para vincular tu cuenta. Vence en 10 minutos. No compartas este código.` : 'No se pudo crear el código. Inténtalo más tarde.';
return { json: { chatId, text } };

const origen = $('Preparar respuesta segura').item.json;
const chatId = origen.chatId;
const seccion = origen.seccion;
const fecha = valor => valor ? String(valor).slice(0, 10) : 'sin fecha';
const texto = valor => String(valor ?? '').replace(/[\r\n]+/g, ' ').trim();
const lineas = [];
let titulo = '';
if ($json.error) {
  return { json: { chatId, text: 'No pude consultar tus datos ahora. Inténtalo de nuevo más tarde.' } };
}
if (!$json.vinculada) {
  return { json: { chatId, text: 'Este chat aún no está vinculado a una cuenta activa. Inicia sesión en la aplicación, envía /vincular y pega el código en “Mi información”.' } };
}
if (seccion === 'perfil') {
  titulo = 'Tu perfil';
  const p = $json.perfil ?? {};
  lineas.push(`Nombre: ${texto(p.nombre) || 'no registrado'}`);
  lineas.push(`Fecha de nacimiento: ${fecha(p.fechaNacimiento)}`);
  lineas.push(`Teléfono: ${texto(p.telefono) || 'no registrado'}`);
  lineas.push(`Telegram: ${p.telegramVerificado ? 'vinculado' : 'no vinculado'}`);
} else if (seccion === 'mediciones') {
  titulo = 'Últimas mediciones guardadas';
  const items = $json.mediciones ?? [];
  for (const m of items) {
    let valor = m.tipo === 'glucosa' ? `${m.glucosaMgDl} mg/dL`
      : m.tipo === 'presion_arterial' ? `${m.sistolicaMmhg}/${m.diastolicaMmhg} mmHg`
      : m.tipo === 'hba1c' ? `${m.hba1cPercent}%` : 'valor no disponible';
    lineas.push(`${fecha(m.fechaHora)} · ${valor}${m.contexto ? ` · ${texto(m.contexto)}` : ''}`);
  }
  if (!items.length) lineas.push('No hay mediciones registradas.');
} else if (seccion === 'medicamentos') {
  titulo = 'Medicamentos registrados';
  const items = $json.medicamentos ?? [];
  for (const m of items) {
    const horas = (m.horarios ?? []).join(', ');
    lineas.push(`${texto(m.nombre)} · ${texto(m.dosis)} · ${texto(m.frecuencia)}${horas ? ` · horarios: ${horas}` : ''} · desde ${fecha(m.fechaInicio)}${m.fechaFin ? ` hasta ${fecha(m.fechaFin)}` : ''}`);
  }
  if (!items.length) lineas.push('No hay medicamentos registrados.');
} else if (seccion === 'alertas') {
  titulo = 'Alertas registradas';
  const items = $json.alertas ?? [];
  for (const a of items) {
    const medicion = a.medicion?.tipo === 'glucosa' ? `${a.medicion.valor} mg/dL`
      : a.medicion?.tipo === 'presion_arterial' ? `${a.medicion.sistolica}/${a.medicion.diastolica} mmHg`
        : a.medicion?.tipo === 'hba1c' ? `${a.medicion.valor}%` : null;
    lineas.push(`${fecha(a.fechaGeneracion)} · ${texto(a.tipo)} · ${texto(a.estado)}${medicion ? ` · medición: ${medicion}` : ''}${a.motivo ? `\n${texto(a.motivo)}` : ''}${a.criterioActivado ? `\nCriterio: ${texto(a.criterioActivado)}` : ''}${a.fuente?.titulo ? `\nFuente: ${texto(a.fuente.institucion)} — ${texto(a.fuente.titulo)}` : ''}${a.indicacionPaciente ? `\nIndicación registrada: ${texto(a.indicacionPaciente)}` : ''}`);
  }
  if (!items.length) lineas.push('No hay alertas registradas.');
} else if (seccion === 'diagnosticos') {
  titulo = 'Diagnósticos confirmados';
  const nombres = { diabetes_tipo_1: 'Diabetes tipo 1', diabetes_tipo_2: 'Diabetes tipo 2', hipertension: 'Hipertensión arterial' };
  const items = $json.diagnosticos ?? [];
  for (const d of items) lineas.push(`${nombres[d.codigo] ?? texto(d.codigo)} · ${texto(d.estado)} · confirmado ${fecha(d.confirmadoEn)}`);
  if (!items.length) lineas.push('No hay diagnósticos confirmados registrados.');
} else if (seccion === 'objetivos') {
  titulo = 'Objetivos registrados por tu médico';
  const items = $json.objetivos ?? [];
  for (const o of items) {
    let rango = o.tipoMedicion === 'glucosa' ? `${o.glucosaMin ?? '—'} a ${o.glucosaMax ?? '—'} mg/dL`
      : `${o.sistolicaMin ?? '—'}–${o.sistolicaMax ?? '—'} / ${o.diastolicaMin ?? '—'}–${o.diastolicaMax ?? '—'} mmHg`;
    lineas.push(`${texto(o.tipoMedicion)}${o.contexto ? ` · ${texto(o.contexto)}` : ''} · ${rango} · ${texto(o.estado)}${o.indicacionPaciente ? `\nIndicación registrada: ${texto(o.indicacionPaciente)}` : ''}`);
  }
  if (!items.length) lineas.push('No hay objetivos registrados.');
}
let respuesta = `${titulo}\n\n${lineas.join('\n')}`;
if (respuesta.length > 3800) respuesta = `${respuesta.slice(0, 3780)}\n… Consulta el historial completo en la aplicación.`;
return { json: { chatId, text: respuesta } };
